// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "./common/IERC20.sol";
import "./common/Ownable.sol";
import "./interfaces/IADAIToken.sol";

/**
 * @title ADAIToken (AnyDexAI Coin)
 * @notice BEP-20 / ERC-20 Token for AnyDexAI Ecosystem
 * @dev Controlled minting architecture for Main Plan rewards and Gaming Engine
 */
contract ADAIToken is IADAIToken, Ownable {
    string private _name = "AnyDexAI Coin";
    string private _symbol = "ADAI";
    uint8 private constant _decimals = 18;
    uint256 private _totalSupply;

    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    mapping(address => bool) private _minters;

    event MinterStatusUpdated(address indexed account, bool isMinter);

    modifier onlyMinter() {
        require(_minters[msg.sender] || owner() == msg.sender, "ADAI: caller is not authorized minter");
        _;
    }

    constructor(address initialOwner) Ownable(initialOwner) {
        // Owner is authorized minter by default
        _minters[initialOwner] = true;
        emit MinterStatusUpdated(initialOwner, true);
    }

    function name() external pure override returns (string memory) {
        return "AnyDexAI Coin";
    }

    function symbol() external pure override returns (string memory) {
        return "ADAI";
    }

    function decimals() external pure override returns (uint8) {
        return _decimals;
    }

    function totalSupply() external view override returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) external view override returns (uint256) {
        return _balances[account];
    }

    function isMinter(address account) external view override returns (bool) {
        return _minters[account];
    }

    function setMinter(address minterAddress, bool status) external onlyOwner {
        require(minterAddress != address(0), "ADAI: zero address minter");
        _minters[minterAddress] = status;
        emit MinterStatusUpdated(minterAddress, status);
    }

    function transfer(address to, uint256 value) external override returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function allowance(address tokenOwner, address spender) external view override returns (uint256) {
        return _allowances[tokenOwner][spender];
    }

    function approve(address spender, uint256 value) external override returns (bool) {
        _approve(msg.sender, spender, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external override returns (bool) {
        address spender = msg.sender;
        uint256 currentAllowance = _allowances[from][spender];
        if (currentAllowance != type(uint256).max) {
            require(currentAllowance >= value, "ADAI: insufficient allowance");
            unchecked {
                _approve(from, spender, currentAllowance - value);
            }
        }
        _transfer(from, to, value);
        return true;
    }

    function mint(address to, uint256 amount) external override onlyMinter {
        require(to != address(0), "ADAI: mint to zero address");
        _totalSupply += amount;
        unchecked {
            _balances[to] += amount;
        }
        emit Transfer(address(0), to, amount);
    }

    function burn(uint256 amount) external override {
        _burn(msg.sender, amount);
    }

    function burnFrom(address account, uint256 amount) external override {
        uint256 currentAllowance = _allowances[account][msg.sender];
        if (currentAllowance != type(uint256).max) {
            require(currentAllowance >= amount, "ADAI: insufficient allowance to burn");
            unchecked {
                _approve(account, msg.sender, currentAllowance - amount);
            }
        }
        _burn(account, amount);
    }

    function _transfer(address from, address to, uint256 value) internal {
        require(from != address(0), "ADAI: transfer from zero address");
        require(to != address(0), "ADAI: transfer to zero address");

        uint256 fromBalance = _balances[from];
        require(fromBalance >= value, "ADAI: transfer amount exceeds balance");
        unchecked {
            _balances[from] = fromBalance - value;
            _balances[to] += value;
        }
        emit Transfer(from, to, value);
    }

    function _approve(address tokenOwner, address spender, uint256 value) internal {
        require(tokenOwner != address(0), "ADAI: approve from zero address");
        require(spender != address(0), "ADAI: approve to zero address");
        _allowances[tokenOwner][spender] = value;
        emit Approval(tokenOwner, spender, value);
    }

    function _burn(address account, uint256 amount) internal {
        require(account != address(0), "ADAI: burn from zero address");
        uint256 accountBalance = _balances[account];
        require(accountBalance >= amount, "ADAI: burn amount exceeds balance");
        unchecked {
            _balances[account] = accountBalance - amount;
            _totalSupply -= amount;
        }
        emit Transfer(account, address(0), amount);
    }
}

contracts/AnyDexAIMain.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "./interfaces/IERC20.sol";
import "./utils/SafeERC20.sol";
import "./utils/Ownable.sol";
import "./utils/ReentrancyGuard.sol";
import "./tokens/ADAI.sol";
import "./tokens/AnyDexAINFT.sol";

/**
 * @title AnyDexAIMain
 * @notice Core Staking, Affiliate, ROI, and Reward Contract for ANYDEXAI.
 * @dev Handles BEP20 USDT investments, 200% capped ROI with ADAI capital refunds,
 *      immediate 3-tier direct referral, 5-tier level income with 120-day activity enforcement,
 *      9-grade NFT rewards, liquidity splits, and 2x monthly income capping.
 */
contract AnyDexAIMain is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // --- CONTRACT REFERENCES ---
    IERC20 public immutable usdt;
    ADAI public immutable adaiToken;
    AnyDexAINFT public immutable nftContract;

    // --- LIQUIDITY WALLETS (0.5% + 0.5%) ---
    address public tokenLiquidityWallet;
    address public nftLiquidityWallet;
    uint256 public constant LIQUIDITY_BPS = 50; // 0.5% = 50 basis points (10000 = 100%)

    // --- CONSTANTS ---
    uint256 public constant BPS_DIVISOR = 10000;
    uint256 public constant MONTH = 30 days;
    uint256 public constant ACTIVITY_PERIOD = 120 days; // 120-day referral rule
    uint256 public minWithdrawal = 10 * 1e18; // $10 USDT minimum
    uint256 public maxRoiCapBps = 20000; // 200% ROI limit
    uint256 public adaiCapitalRefundRate = 1e18; // 1 ADAI per 1 USDT of returned capital

    // --- PACKAGES ---
    struct Package {
        uint256 price;          // In USDT (18 decimals)
        uint256 roiBpsPer30d;   // e.g., 500 = 5% / 30 days
        uint256 tokenReward;    // Free ADAI tokens (in 18 decimals)
        bool active;
    }
    mapping(uint256 => Package) public packages;
    uint256 public packageCount;

    // --- USER PROFILE & STAKING ---
    struct UserProfile {
        string name;
        string mobile;
        address sponsor;
        uint256 totalInvested;
        uint256 activeInvested;
        uint256 lastReferralTimestamp;
        uint256 lastLevelClaimTime;
        bool registered;
    }
    mapping(address => UserProfile) public users;

    struct Investment {
        uint256 packageId;
        uint256 amount;
        uint256 startTime;
        uint256 lastClaimTime;
        uint256 totalRoiClaimed;
        bool capitalReturned;
        bool active;
    }
    mapping(address => Investment[]) private _userInvestments;

    // --- DIRECT REFERRAL (7%, 2%, 1%) ---
    uint256[3] public directReferralBps = [700, 200, 100]; // 7%, 2%, 1%

    // --- LEVEL INCOME CONFIGURATION (Levels 1 to 5) ---
    struct LevelConfig {
        uint256 roiBpsPer30d;
        uint256 minMembers;
        uint256 minCumulativeVolume;
    }
    // Level index 0 to 4 (representing Level 1 to 5)
    LevelConfig[5] public levelConfigs;

    // Downline stats: user => level (0..5) => count & volume
    mapping(address => mapping(uint256 => uint256)) public levelMemberCount;
    mapping(address => mapping(uint256 => uint256)) public levelBusinessVolume;

    // --- 2x MONTHLY CEILING TRACKING ---
    // user => (timestamp / 30 days) => total referral + level income credited
    mapping(address => mapping(uint256 => uint256)) public monthlyAffiliateIncome;

    // --- NFT GRADE QUALIFICATIONS (Tiers 1 to 6) ---
    struct NFTGradeRequirement {
        uint8 level;            // 1 to 6
        uint256 minMembers;
        uint256 minVolume;
    }
    NFTGradeRequirement[6] public nftGradeRequirements;

    // Pending claimable earnings in USDT (e.g. overflow, ROI, level income)
    mapping(address => uint256) public claimableUSDT;

    // --- EVENTS ---
    event UserRegistered(address indexed user, address indexed sponsor, string name, string mobile, uint256 packageId, uint256 amount, uint256 timestamp);
    event Invested(address indexed user, uint256 packageId, uint256 amount, uint256 investmentIndex);
    event DirectReferralPaid(address indexed upline, address indexed fromUser, uint8 level, uint256 amount);
    event DirectReferralCapped(address indexed upline, uint256 paid, uint256 capped);
    event RoiClaimed(address indexed user, uint256 indexed investmentIndex, uint256 amount);
    event CapitalReturnedInADAI(address indexed user, uint256 indexed investmentIndex, uint256 adaiAmount);
    event LevelIncomeClaimed(address indexed user, uint256 amount);
    event EarningsWithdrawn(address indexed user, uint256 amount);
    event PackageUpdated(uint256 indexed packageId, uint256 price, uint256 roiBpsPer30d, uint256 tokenReward, bool active);
    event NFTGradeAwarded(address indexed user, uint8 tier);
    event EmergencyUSDTWithdrawn(address indexed owner, uint256 amount);

    constructor(
        address _usdt,
        address _adaiToken,
        address _nftContract,
        address _tokenLiquidityWallet,
        address _nftLiquidityWallet
    ) Ownable(msg.sender) {
        require(_usdt != address(0) && _adaiToken != address(0) && _nftContract != address(0), "Invalid contract address");
        require(_tokenLiquidityWallet != address(0) && _nftLiquidityWallet != address(0), "Invalid liquidity wallet");

        usdt = IERC20(_usdt);
        adaiToken = ADAI(_adaiToken);
        nftContract = AnyDexAINFT(_nftContract);
        tokenLiquidityWallet = _tokenLiquidityWallet;
        nftLiquidityWallet = _nftLiquidityWallet;

        // Initialize 3 default packages
        // 1: $1,000 -> 5%/30d -> 10 ADAI
        _createPackage(1000 * 1e18, 500, 10 * 1e18);
        // 2: $5,000 -> 5.5%/30d -> 50 ADAI
        _createPackage(5000 * 1e18, 550, 50 * 1e18);
        // 3: $10,000 -> 6%/30d -> 100 ADAI
        _createPackage(10000 * 1e18, 600, 100 * 1e18);

        // Initialize Level Income Requirements (Levels 1 to 5)
        // Level 1: 1% / 30d (100 bps) - min 5 members, $5,000 L1
        levelConfigs[0] = LevelConfig(100, 5, 5000 * 1e18);
        // Level 2: 0.5% / 30d (50 bps) - min 2 members in L2, $9,000 cumulative L1-L2
        levelConfigs[1] = LevelConfig(50, 2, 9000 * 1e18);
        // Level 3: 0.5% / 30d (50 bps) - min 2 members in L3, $14,000 cumulative L1-L3
        levelConfigs[2] = LevelConfig(50, 2, 14000 * 1e18);
        // Level 4: 0.25% / 30d (25 bps) - min 4 members in L4, $18,000 cumulative L1-L4
        levelConfigs[3] = LevelConfig(25, 4, 18000 * 1e18);
        // Level 5: 0.25% / 30d (25 bps) - min 5 members in L5, $25,000 cumulative L1-L5
        levelConfigs[4] = LevelConfig(25, 5, 25000 * 1e18);

        // Initialize NFT Grade Requirements (Grades 1 to 6)
        // Token Squire: L1, 3 members, $5,000
        nftGradeRequirements[0] = NFTGradeRequirement(1, 3, 5000 * 1e18);
        // Coin Knight: L2, 9 members, $15,000
        nftGradeRequirements[1] = NFTGradeRequirement(2, 9, 15000 * 1e18);
        // Captain Creator: L3, 27 members, $45,000
        nftGradeRequirements[2] = NFTGradeRequirement(3, 27, 45000 * 1e18);
        // Lord Validator: L4, 81 members, $135,000
        nftGradeRequirements[3] = NFTGradeRequirement(4, 81, 135000 * 1e18);
        // Baren Hash: L5, 243 members, $405,000
        nftGradeRequirements[4] = NFTGradeRequirement(5, 243, 405000 * 1e18);
        // Alpha Duke: L6, 729 members, $1,215,000
        nftGradeRequirements[5] = NFTGradeRequirement(6, 729, 1215000 * 1e18);
    }

    // --- REGISTRATION & INVESTMENT ---

    /**
     * @notice Registers user (if new) and stakes into a selected package.
     * @param packageId ID of the package (1, 2, 3...)
     * @param sponsor Address of the referring sponsor
     * @param name User's display name for database/UI
     * @param mobile User's contact mobile number
     */
    function invest(
        uint256 packageId,
        address sponsor,
        string calldata name,
        string calldata mobile
    ) external nonReentrant {
        Package memory pack = packages[packageId];
        require(pack.active, "Package is not active");

        UserProfile storage profile = users[msg.sender];
        bool isNewUser = !profile.registered;

        if (isNewUser) {
            // First time registration
            if (sponsor == address(0) || sponsor == msg.sender) {
                sponsor = owner(); // Default fallback to owner
            }
            require(users[sponsor].registered || sponsor == owner(), "Invalid sponsor");

            profile.name = name;
            profile.mobile = mobile;
            profile.sponsor = sponsor;
            profile.registered = true;
            profile.lastLevelClaimTime = block.timestamp;

            // Mint Entry Pass NFT (Tier 0)
            if (!nftContract.hasTierNFT(msg.sender, 0)) {
                nftContract.mintGradeNFT(msg.sender, 0);
            }

            // Update sponsor's last referral timestamp (for 120-day activity rule)
            users[sponsor].lastReferralTimestamp = block.timestamp;

            emit UserRegistered(msg.sender, sponsor, name, mobile, packageId, pack.price, block.timestamp);
        } else {
            // Existing user re-investing
            sponsor = profile.sponsor;
        }

        // Transfer USDT from user to this contract
        usdt.safeTransferFrom(msg.sender, address(this), pack.price);

        // 0.5% Token Liquidity + 0.5% NFT Liquidity
        uint256 tokenLiqAmount = (pack.price * LIQUIDITY_BPS) / BPS_DIVISOR;
        uint256 nftLiqAmount = (pack.price * LIQUIDITY_BPS) / BPS_DIVISOR;
        usdt.safeTransfer(tokenLiquidityWallet, tokenLiqAmount);
        usdt.safeTransfer(nftLiquidityWallet, nftLiqAmount);

        // Mint welcome ADAI tokens to user
        if (pack.tokenReward > 0) {
            try adaiToken.mint(msg.sender, pack.tokenReward) {} catch {}
            // Sponsor gets 50% sponsor tokens for every registration
            if (sponsor != address(0)) {
                uint256 sponsorTokens = pack.tokenReward / 2;
                if (sponsorTokens > 0) {
                    try adaiToken.mint(sponsor, sponsorTokens) {} catch {}
                }
            }
        }

        // Record investment
        profile.totalInvested += pack.price;
        profile.activeInvested += pack.price;
        _userInvestments[msg.sender].push(Investment({
            packageId: packageId,
            amount: pack.price,
            startTime: block.timestamp,
            lastClaimTime: block.timestamp,
            totalRoiClaimed: 0,
            capitalReturned: false,
            active: true
        }));
        uint256 invIndex = _userInvestments[msg.sender].length - 1;

        // Update downline stats & distribute immediate direct referral (7%, 2%, 1%)
        _processDownlineAndDirectReferral(msg.sender, pack.price, isNewUser);

        emit Invested(msg.sender, packageId, pack.price, invIndex);
    }

    /**
     * @dev Updates downline volume/counts up to 6 levels, pays immediate 3-tier referral, and checks NFT upgrades.
     */
    function _processDownlineAndDirectReferral(address user, uint256 amount, bool isNewUser) internal {
        address currentUpline = users[user].sponsor;

        for (uint8 lvl = 0; lvl < 6; lvl++) {
            if (currentUpline == address(0)) break;

            // Update stats
            if (isNewUser) {
                levelMemberCount[currentUpline][lvl] += 1;
            }
            levelBusinessVolume[currentUpline][lvl] += amount;

            // Immediate 3-tier direct referral for levels 0, 1, 2 (Level 1, 2, 3)
            if (lvl < 3) {
                _payImmediateReferral(currentUpline, user, lvl + 1, (amount * directReferralBps[lvl]) / BPS_DIVISOR);
            }

            // Check if upline qualifies for grade NFT at this level
            _checkAndAwardNFT(currentUpline, lvl);

            currentUpline = users[currentUpline].sponsor;
        }
    }

    /**
     * @dev Pays immediate direct referral to upline, enforcing the monthly 2x capital ceiling.
     */
    function _payImmediateReferral(address upline, address fromUser, uint8 levelNum, uint256 grossAmount) internal {
        if (grossAmount == 0 || upline == address(0)) return;

        uint256 monthEpoch = block.timestamp / MONTH;
        uint256 currentMonthlyEarned = monthlyAffiliateIncome[upline][monthEpoch];
        uint256 monthlyCeiling = users[upline].activeInvested * 2;

        // If upline is owner, bypass 2x ceiling
        if (upline == owner()) {
            monthlyCeiling = type(uint256).max;
        }

        uint256 payableAmount = 0;
        if (currentMonthlyEarned < monthlyCeiling) {
            uint256 room = monthlyCeiling - currentMonthlyEarned;
            payableAmount = grossAmount > room ? room : grossAmount;
            monthlyAffiliateIncome[upline][monthEpoch] += payableAmount;
        }

        if (payableAmount > 0) {
            usdt.safeTransfer(upline, payableAmount);
            emit DirectReferralPaid(upline, fromUser, levelNum, payableAmount);
        }

        if (grossAmount > payableAmount) {
            emit DirectReferralCapped(upline, payableAmount, grossAmount - payableAmount);
        }
    }

    // --- NFT GRADE CHECKS & AWARDS ---

    function _checkAndAwardNFT(address upline, uint8 levelIndex) internal {
        if (levelIndex >= 6) return;

        uint8 tier = levelIndex + 1; // Tier 1 to 6
        if (nftContract.hasTierNFT(upline, tier)) return;

        NFTGradeRequirement memory req = nftGradeRequirements[levelIndex];
        if (levelMemberCount[upline][levelIndex] >= req.minMembers && levelBusinessVolume[upline][levelIndex] >= req.minVolume) {
            try nftContract.mintGradeNFT(upline, tier) {
                emit NFTGradeAwarded(upline, tier);
            } catch {}
        }
    }

    // --- ROI CALCULATION & CLAIM ---

    /**
     * @notice Calculates pending ROI across all investments for a user.
     * @dev ROI is capped at 200% of the invested amount.
     */
    function calculatePendingROI(address user) public view returns (uint256 totalPendingRoi) {
        Investment[] memory invs = _userInvestments[user];
        for (uint256 i = 0; i < invs.length; i++) {
            if (!invs[i].active) continue;

            Package memory pack = packages[invs[i].packageId];
            uint256 timeElapsed = block.timestamp - invs[i].lastClaimTime;
            uint256 accrued = (invs[i].amount * pack.roiBpsPer30d * timeElapsed) / (MONTH * BPS_DIVISOR);

            uint256 maxTotalRoi = (invs[i].amount * maxRoiCapBps) / BPS_DIVISOR; // 200%
            if (invs[i].totalRoiClaimed + accrued > maxTotalRoi) {
                accrued = maxTotalRoi > invs[i].totalRoiClaimed ? maxTotalRoi - invs[i].totalRoiClaimed : 0;
            }
            totalPendingRoi += accrued;
        }
    }

    /**
     * @notice Claims accrued ROI for all investments.
     * @dev When an investment reaches 200% ROI, its active flag turns off,
     *      and its capital is refunded in ADAI tokens!
     */
    function claimROI() public nonReentrant returns (uint256 totalClaimed) {
        return _claimROI(msg.sender);
    }

    function _claimROI(address user) internal returns (uint256 totalClaimed) {
        Investment[] storage invs = _userInvestments[user];
        uint256 length = invs.length;

        for (uint256 i = 0; i < length; i++) {
            if (!invs[i].active) continue;

            Package memory pack = packages[invs[i].packageId];
            uint256 timeElapsed = block.timestamp - invs[i].lastClaimTime;
            uint256 accrued = (invs[i].amount * pack.roiBpsPer30d * timeElapsed) / (MONTH * BPS_DIVISOR);

            uint256 maxTotalRoi = (invs[i].amount * maxRoiCapBps) / BPS_DIVISOR; // 200%
            if (invs[i].totalRoiClaimed + accrued >= maxTotalRoi) {
                accrued = maxTotalRoi > invs[i].totalRoiClaimed ? maxTotalRoi - invs[i].totalRoiClaimed : 0;
                invs[i].totalRoiClaimed = maxTotalRoi;
                invs[i].lastClaimTime = block.timestamp;
                invs[i].active = false;
                if (users[user].activeInvested >= invs[i].amount) {
                    users[user].activeInvested -= invs[i].amount;
                } else {
                    users[user].activeInvested = 0;
                }

                // Capital return via ADAI tokens after 200% completed
                if (!invs[i].capitalReturned) {
                    invs[i].capitalReturned = true;
                    uint256 adaiRefund = (invs[i].amount * adaiCapitalRefundRate) / 1e18;
                    try adaiToken.mint(user, adaiRefund) {
                        emit CapitalReturnedInADAI(user, i, adaiRefund);
                    } catch {}
                }
            } else {
                invs[i].totalRoiClaimed += accrued;
                invs[i].lastClaimTime = block.timestamp;
            }

            totalClaimed += accrued;
            emit RoiClaimed(user, i, accrued);
        }

        if (totalClaimed > 0) {
            claimableUSDT[user] += totalClaimed;
        }
    }

    // --- LEVEL INCOME & 120-DAY RULE ---

    /**
     * @notice Checks if user satisfies the 120-day activity requirement to withdraw level income.
     */
    function is120DayActive(address user) public view returns (bool) {
        if (users[user].lastReferralTimestamp == 0) return false;
        return block.timestamp <= users[user].lastReferralTimestamp + ACTIVITY_PERIOD;
    }

    /**
     * @notice Calculates pending level income for a user across levels 1 to 5.
     */
    function calculatePendingLevelIncome(address user) public view returns (uint256 totalIncome) {
        uint256 timeElapsed = block.timestamp - users[user].lastLevelClaimTime;
        if (timeElapsed == 0) return 0;

        uint256 cumulativeVolume = 0;
        for (uint8 lvl = 0; lvl < 5; lvl++) {
            cumulativeVolume += levelBusinessVolume[user][lvl];
            LevelConfig memory cfg = levelConfigs[lvl];

            // Check eligibility for this level
            if (levelMemberCount[user][lvl] >= cfg.minMembers && cumulativeVolume >= cfg.minCumulativeVolume) {
                uint256 levelVol = levelBusinessVolume[user][lvl];
                uint256 income = (levelVol * cfg.roiBpsPer30d * timeElapsed) / (MONTH * BPS_DIVISOR);
                totalIncome += income;
            }
        }
    }

    /**
     * @notice Claims accrued Level Income.
     * @dev Requires passing the 120-day referral rule and adheres to 2x monthly capital ceiling.
     */
    function claimLevelIncome() public nonReentrant returns (uint256 payableAmount) {
        require(is120DayActive(msg.sender), "120-day rule: must refer a member within 120 days to claim level income");

        uint256 grossIncome = calculatePendingLevelIncome(msg.sender);
        require(grossIncome > 0, "No level income accrued");

        users[msg.sender].lastLevelClaimTime = block.timestamp;

        // Apply 2x monthly ceiling
        uint256 monthEpoch = block.timestamp / MONTH;
        uint256 currentMonthlyEarned = monthlyAffiliateIncome[msg.sender][monthEpoch];
        uint256 monthlyCeiling = users[msg.sender].activeInvested * 2;
        if (msg.sender == owner()) monthlyCeiling = type(uint256).max;

        if (currentMonthlyEarned < monthlyCeiling) {
            uint256 room = monthlyCeiling - currentMonthlyEarned;
            payableAmount = grossIncome > room ? room : grossIncome;
            monthlyAffiliateIncome[msg.sender][monthEpoch] += payableAmount;
        }

        if (payableAmount > 0) {
            claimableUSDT[msg.sender] += payableAmount;
            emit LevelIncomeClaimed(msg.sender, payableAmount);
        }
    }

    // --- WITHDRAWAL (INSTANT PROCESSING, MIN $10) ---

    /**
     * @notice Withdraws all claimable USDT instantly to caller.
     * @dev Also auto-claims pending ROI before executing.
     */
    function withdraw() external nonReentrant {
        // Auto-harvest ROI if available
        uint256 pendingRoi = calculatePendingROI(msg.sender);
        if (pendingRoi > 0) {
            _claimROI(msg.sender);
        }

        uint256 amount = claimableUSDT[msg.sender];
        require(amount >= minWithdrawal, "Withdrawal below minimum $10");

        claimableUSDT[msg.sender] = 0;
        usdt.safeTransfer(msg.sender, amount);

        emit EarningsWithdrawn(msg.sender, amount);
    }

    // --- OWNER CONFIGURATION & MANAGEMENT ---

    function _createPackage(uint256 price, uint256 roiBpsPer30d, uint256 tokenReward) internal {
        packageCount++;
        packages[packageCount] = Package({
            price: price,
            roiBpsPer30d: roiBpsPer30d,
            tokenReward: tokenReward,
            active: true
        });
        emit PackageUpdated(packageCount, price, roiBpsPer30d, tokenReward, true);
    }

    function addPackage(uint256 price, uint256 roiBpsPer30d, uint256 tokenReward) external onlyOwner {
        _createPackage(price, roiBpsPer30d, tokenReward);
    }

    function updatePackage(uint256 packageId, uint256 price, uint256 roiBpsPer30d, uint256 tokenReward, bool active) external onlyOwner {
        require(packageId > 0 && packageId <= packageCount, "Invalid package ID");
        packages[packageId] = Package({
            price: price,
            roiBpsPer30d: roiBpsPer30d,
            tokenReward: tokenReward,
            active: active
        });
        emit PackageUpdated(packageId, price, roiBpsPer30d, tokenReward, active);
    }

    function setLiquidityWallets(address _tokenLiquidityWallet, address _nftLiquidityWallet) external onlyOwner {
        require(_tokenLiquidityWallet != address(0) && _nftLiquidityWallet != address(0), "Invalid address");
        tokenLiquidityWallet = _tokenLiquidityWallet;
        nftLiquidityWallet = _nftLiquidityWallet;
    }

    function setMinWithdrawal(uint256 _minWithdrawal) external onlyOwner {
        minWithdrawal = _minWithdrawal;
    }

    function setDirectReferralRates(uint256 l1, uint256 l2, uint256 l3) external onlyOwner {
        directReferralBps[0] = l1;
        directReferralBps[1] = l2;
        directReferralBps[2] = l3;
    }

    function setLevelConfig(uint8 levelIndex, uint256 roiBpsPer30d, uint256 minMembers, uint256 minCumulativeVolume) external onlyOwner {
        require(levelIndex < 5, "Level index 0 to 4");
        levelConfigs[levelIndex] = LevelConfig(roiBpsPer30d, minMembers, minCumulativeVolume);
    }

    function setAdaiCapitalRefundRate(uint256 newRate) external onlyOwner {
        adaiCapitalRefundRate = newRate;
    }

    function setNftGradeRequirement(uint8 gradeIndex, uint8 level, uint256 minMembers, uint256 minVolume) external onlyOwner {
        require(gradeIndex < 6, "Grade index 0 to 5");
        nftGradeRequirements[gradeIndex] = NFTGradeRequirement(level, minMembers, minVolume);
    }

    /**
     * @notice Allows contract owner to withdraw USDT in emergency or for treasury management.
     */
    function emergencyWithdrawUSDT(uint256 amount) external onlyOwner nonReentrant {
        uint256 bal = usdt.balanceOf(address(this));
        require(amount <= bal, "Amount exceeds balance");
        usdt.safeTransfer(owner(), amount);
        emit EmergencyUSDTWithdrawn(owner(), amount);
    }

    // --- VIEW HELPERS ---

    function getUserInvestments(address user) external view returns (Investment[] memory) {
        return _userInvestments[user];
    }

    function getUserDownlineStats(address user, uint256 level) external view returns (uint256 members, uint256 volume) {
        return (levelMemberCount[user][level], levelBusinessVolume[user][level]);
    }
}

contracts/AnyDexAIMainPlan.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "./common/IERC20.sol";
import "./common/SafeERC20.sol";
import "./common/Ownable.sol";
import "./common/ReentrancyGuard.sol";
import "./interfaces/IADAIToken.sol";
import "./interfaces/IAnyDexAINFT.sol";

/**
 * @title AnyDexAIMainPlan
 * @notice Production-Hardened, Gas-Optimized Core Smart Contract for AnyDexAI (anydexai.com)
 * @dev Handles BEP-20 USDT investments with snapshotted economic terms, 200% ROI ceiling,
 *      ADAI capital return, 3-tier instant direct referral, 5-level monthly income with
 *      strict unlost remainder queue (carrying forward when 2x monthly cap is hit),
 *      120-day activity eligibility enforcement, and 9-tier NFT rewards.
 */
contract AnyDexAIMainPlan is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // --- Custom Errors for Gas Optimization & Audit Clarity ---
    error AlreadyRegistered();
    error NotRegistered();
    error InvalidReferrerID();
    error InvalidPackage();
    error PackageInactive();
    error InvalidSponsor();
    error SponsorNotActive();
    error DurationZero();
    error InvalidRoiPercentage();
    error AmountZero();
    error BelowMinWithdrawal();
    error ActivityRuleViolated();
    error ReachedMonthlyCeiling();
    error InvestmentAlreadyCompleted();
    error NFTNotConfigured();
    error InvalidGrade();
    error GradeAlreadyClaimed();
    error InsufficientLevelMembers();
    error InsufficientLevelVolume();
    error InsufficientUSDTBalance();
    error FeeTooHigh();
    error ReferralPercentageTooHigh();
    error ZeroAddress();
    error IndexOutOfBounds();

    // --- Tokens & External Contracts ---
    IERC20 public immutable usdtToken;
    IADAIToken public adaiToken;
    IAnyDexAINFT public nftContract;

    // --- Platform Wallets & Fee Parameters ---
    address public tokenLiquidityWallet;
    address public nftLiquidityWallet;
    uint256 public tokenLiquidityBps = 50; // 0.5% (Basis points: 10000 = 100%)
    uint256 public nftLiquidityBps = 50;   // 0.5%

    // --- Referral Parameters ---
    uint256 public directReferralL1Bps = 700; // 7%
    uint256 public directReferralL2Bps = 200; // 2%
    uint256 public directReferralL3Bps = 100; // 1%

    // --- Global Rules & Limits ---
    uint256 public minWithdrawal = 10 * 1e18; // 10 USDT minimum withdrawal
    uint256 public constant MAX_EARNINGS_MULTIPLIER = 2; // Monthly ceiling: 2x of active capital
    uint256 public constant ACTIVITY_WINDOW_DAYS = 120 days; // 120-day referral rule
    uint256 public constant MONTH_DURATION = 30 days;
    uint256 public constant BPS_DENOMINATOR = 10000;

    // Configurable ADAI Capital Refund Rate (1e18 = 1 USDT per 1 ADAI)
    uint256 public adaiCapitalRefundRate = 1e18;

    // --- Package Struct & Mapping ---
    struct Package {
        uint256 amount;          // Package price in USDT (wei)
        uint256 roiBasisPoints;  // ROI percentage in basis points (e.g. 500 = 5%)
        uint256 durationDays;    // ROI period in days (e.g. 30 days)
        uint256 tokenReward;     // ADAI tokens minted to user on registration
        bool isActive;
    }

    uint256 public packageCount;
    mapping(uint256 => Package) public packages;

    // --- Gas-Optimized, Packed Investment Record with Term Snapshotting ---
    // Slot 0 (32 bytes): capital (16 bytes) + totalRoiClaimed (16 bytes)
    // Slot 1 (21 bytes <= 32 bytes): startTime (6) + lastClaimTime (6) + packageId (4) + roiBasisPoints (2) + durationDays (2) + completed (1)
    struct Investment {
        uint128 capital;          // Package capital in USDT wei
        uint128 totalRoiClaimed;  // Total USDT ROI claimed (up to 200% = 2x capital)
        uint48 startTime;         // Timestamp when investment began
        uint48 lastClaimTime;     // Timestamp of last ROI claim
        uint32 packageId;         // Reference package ID
        uint16 roiBasisPoints;    // SNAPSHOT: Fixed ROI bps at deposit time (e.g. 500 = 5%)
        uint16 durationDays;      // SNAPSHOT: Fixed duration in days at deposit time (e.g. 30)
        bool completed;           // True when 200% ROI is reached
    }

    // --- Level Income Criteria Struct ---
    struct LevelCriteria {
        uint256 roiBps;            // e.g. 100 = 1.0%, 50 = 0.5%, 25 = 0.25%
        uint256 requiredMembers;   // Members needed on this level
        uint256 requiredTeamVolume;// Cumulative business volume required
    }

    mapping(uint8 => LevelCriteria) public levelConfigs; // Levels 1 to 5

    // --- NFT Grade Criteria Struct ---
    struct NFTGradeCriteria {
        uint8 level;               // Level required
        uint256 requiredMembers;   // Minimum team count
        uint256 requiredVolume;    // Minimum team volume
    }

    mapping(uint8 => NFTGradeCriteria) public nftGradeConfigs; // Grades 1 to 8

    // --- User Profile Struct ---
    struct User {
        bool isExist;                 // Compatibility with BnbSmarttMatrix style
        uint256 id;
        bool isRegistered;
        address sponsor;
        uint256 referrerID;           // Tree parent / referrer ID (BnbSmarttMatrix style)
        uint256 sponsorID;            // Direct inviter ID (BnbSmarttMatrix style)
        uint256 activeCapital;
        uint256 totalCapitalInvested;
        uint256 lastReferralTimestamp;
        uint256 pendingLevelIncome;   // Preserved unpaid level income (carried forward)
        uint256 lastLevelAccrualTime;
        // Monthly Earnings Cap Tracker (Direct + Level Income <= 2x active capital)
        uint256 currentMonthStartTime;
        uint256 currentMonthEarnings;
        // Downline tracking
        uint256 directCount;
        uint256 level1Business;
        uint256 totalTeamBusiness;
        address[] referrals;          // Direct children referrals (BnbSmarttMatrix style)
    }

    uint256 public totalUsers;
    uint256 public currentId;         // BnbSmarttMatrix alias for totalUsers
    mapping(uint256 => address) public idToAddress;
    mapping(uint256 => address) public userList; // BnbSmarttMatrix alias for idToAddress
    mapping(address => uint256) public addressToId;

    mapping(address => User) public users;
    mapping(address => Investment[]) public userInvestments;
    // user => level (1..8) => member count
    mapping(address => mapping(uint8 => uint256)) public userDownlineCount;
    // user => level (1..8) => business volume
    mapping(address => mapping(uint8 => uint256)) public userDownlineVolume;

    // --- Events ---
    event Registered(address indexed user, address indexed sponsor, uint256 packageId, uint256 timestamp);
    event Invested(address indexed user, uint256 packageId, uint256 amount);
    event DirectReferralPaid(address indexed beneficiary, address indexed fromUser, uint8 level, uint256 amount);
    event DirectReferralCapped(address indexed beneficiary, address indexed fromUser, uint8 level, uint256 rawAmount, uint256 paidAmount);
    event RoiClaimed(address indexed user, uint256 indexed investmentIndex, uint256 amount);
    event CapitalReturnedViaADAI(address indexed user, uint256 indexed investmentIndex, uint256 adaiAmount);
    event LevelIncomeAccrued(address indexed user, uint256 amount);
    event LevelIncomeWithdrawn(address indexed user, uint256 paidAmount, uint256 pendingRemainder);
    event NFTGradeClaimed(address indexed user, uint8 gradeId);
    event PackageAdded(uint256 indexed packageId, uint256 amount, uint256 roiBps, uint256 durationDays, uint256 tokenReward);
    event PackageUpdated(uint256 indexed packageId, uint256 amount, uint256 roiBps, uint256 durationDays, uint256 tokenReward, bool isActive);
    event PackageRoiAndDurationUpdated(uint256 indexed packageId, uint256 oldRoiBps, uint256 newRoiBps, uint256 oldDurationDays, uint256 newDurationDays);
    event AdaiRefundRateUpdated(uint256 newRate);
    event AdminWithdrawal(address indexed recipient, uint256 amount);

    constructor(
        address initialOwner,
        address _usdtAddress,
        address _tokenLiqWallet,
        address _nftLiqWallet
    ) Ownable(initialOwner) {
        if (_usdtAddress == address(0) || _tokenLiqWallet == address(0) || _nftLiqWallet == address(0)) {
            revert ZeroAddress();
        }

        usdtToken = IERC20(_usdtAddress);
        tokenLiquidityWallet = _tokenLiqWallet;
        nftLiquidityWallet = _nftLiqWallet;

        // Initialize Default Packages: $1k (5%/30d), $5k (5.5%/30d), $10k (6%/30d)
        _createPackage(1000 * 1e18, 500, 30, 10 * 1e18);
        _createPackage(5000 * 1e18, 550, 30, 50 * 1e18);
        _createPackage(10000 * 1e18, 600, 30, 100 * 1e18);

        // Initialize Level Income Requirements (Levels 1 to 5)
        levelConfigs[1] = LevelCriteria(100, 5, 5000 * 1e18);    // L1: 1.0%/30d, 5 members, $5k
        levelConfigs[2] = LevelCriteria(50, 2, 9000 * 1e18);     // L2: 0.5%/30d, 2 members, $9k L1+L2
        levelConfigs[3] = LevelCriteria(50, 2, 14000 * 1e18);    // L3: 0.5%/30d, 2 members, $14k L1..L3
        levelConfigs[4] = LevelCriteria(25, 4, 18000 * 1e18);    // L4: 0.25%/30d, 4 members, $18k L1..L4
        levelConfigs[5] = LevelCriteria(25, 5, 25000 * 1e18);    // L5: 0.25%/30d, 5 members, $25k L1..L5

        // Initialize NFT Grade Criteria (3x Progression Matrix)
        nftGradeConfigs[1] = NFTGradeCriteria(1, 3, 5000 * 1e18);       // Token Squire
        nftGradeConfigs[2] = NFTGradeCriteria(2, 9, 15000 * 1e18);      // Coin Knight
        nftGradeConfigs[3] = NFTGradeCriteria(3, 27, 45000 * 1e18);     // Captain Creator
        nftGradeConfigs[4] = NFTGradeCriteria(4, 81, 135000 * 1e18);    // Lord Validator
        nftGradeConfigs[5] = NFTGradeCriteria(5, 243, 405000 * 1e18);   // Baren Hash
        nftGradeConfigs[6] = NFTGradeCriteria(6, 729, 1215000 * 1e18);  // Alpha Duke
        nftGradeConfigs[7] = NFTGradeCriteria(7, 2187, 3645000 * 1e18); // Royal Archon
        nftGradeConfigs[8] = NFTGradeCriteria(8, 6561, 10935000 * 1e18);// AnyDex Sovereign

        // Root Deployer / Owner User Registration with default maximum levels (User ID 1)
        address rootOwner = initialOwner != address(0) ? initialOwner : msg.sender;
        totalUsers = 1;
        currentId = 1;
        idToAddress[1] = rootOwner;
        userList[1] = rootOwner;
        addressToId[rootOwner] = 1;
        users[rootOwner].isExist = true;
        users[rootOwner].id = 1;
        users[rootOwner].isRegistered = true;
        users[rootOwner].lastReferralTimestamp = block.timestamp;
        users[rootOwner].currentMonthStartTime = block.timestamp;
        users[rootOwner].lastLevelAccrualTime = block.timestamp;
        emit Registered(rootOwner, address(0), 1, block.timestamp);
    }

    function getUserAddress(uint256 userId) external view returns (address) {
        return idToAddress[userId];
    }

    function getUserId(address userAddr) external view returns (uint256) {
        return addressToId[userAddr];
    }

    // --- External Setters for Tokens ---
    function setTokenAndNFTContracts(address _adaiToken, address _nftContract) external onlyOwner {
        if (_adaiToken == address(0) || _nftContract == address(0)) revert ZeroAddress();
        adaiToken = IADAIToken(_adaiToken);
        nftContract = IAnyDexAINFT(_nftContract);
    }

    function setAdaiCapitalRefundRate(uint256 newRate) external onlyOwner {
        if (newRate == 0) revert AmountZero();
        adaiCapitalRefundRate = newRate;
        emit AdaiRefundRateUpdated(newRate);
    }

    // --- BnbSmarttMatrix Style Registration & Investment ---

    /**
     * @notice Registers a new user with a referrer ID (BnbSmarttMatrix style)
     * @param _referrerID The numeric ID of the sponsor (e.g. 1 for Root Owner)
     */
    function regUser(uint256 _referrerID) public nonReentrant {
        if (users[msg.sender].isRegistered || users[msg.sender].isExist) revert AlreadyRegistered();
        if (_referrerID == 0 || _referrerID > totalUsers) revert InvalidReferrerID();

        address sponsorAddr = idToAddress[_referrerID];
        if (sponsorAddr == address(0) || sponsorAddr == msg.sender) revert InvalidSponsor();
        if (!users[sponsorAddr].isRegistered && sponsorAddr != owner()) revert SponsorNotActive();

        _registerUserInternal(msg.sender, sponsorAddr, _referrerID);
    }

    /**
     * @notice Registers a new user with a referrer address (BnbSmarttMatrix style)
     * @param _referrer The address of the sponsor
     */
    function regUser(address _referrer) public nonReentrant {
        if (users[msg.sender].isRegistered || users[msg.sender].isExist) revert AlreadyRegistered();
        if (_referrer == address(0) || _referrer == msg.sender) revert InvalidSponsor();
        if (!users[_referrer].isRegistered && _referrer != owner()) revert SponsorNotActive();

        uint256 sponsorId = addressToId[_referrer];
        _registerUserInternal(msg.sender, _referrer, sponsorId);
    }

    /**
     * @notice Registers a new user with a referrer ID and immediately purchases an investment package
     * @param _referrerID The numeric ID of the sponsor
     * @param _packageId The package ID to purchase with USDT
     */
    function regUser(uint256 _referrerID, uint256 _packageId) external nonReentrant {
        if (!users[msg.sender].isRegistered && !users[msg.sender].isExist) {
            if (_referrerID == 0 || _referrerID > totalUsers) revert InvalidReferrerID();
            address sponsorAddr = idToAddress[_referrerID];
            if (sponsorAddr == address(0) || sponsorAddr == msg.sender) revert InvalidSponsor();
            if (!users[sponsorAddr].isRegistered && sponsorAddr != owner()) revert SponsorNotActive();
            _registerUserInternal(msg.sender, sponsorAddr, _referrerID);
        }
        _investInternal(msg.sender, _packageId);
    }

    /**
     * @notice Purchase an investment package for an already registered user
     * @param packageId ID of the package to purchase
     */
    function buyPackage(uint256 packageId) external nonReentrant {
        if (!users[msg.sender].isRegistered) revert NotRegistered();
        _investInternal(msg.sender, packageId);
    }

    /**
     * @notice Invest in an AnyDexAI package for an already registered user
     * @param packageId ID of the package to purchase
     */
    function invest(uint256 packageId) external nonReentrant {
        if (!users[msg.sender].isRegistered) revert NotRegistered();
        _investInternal(msg.sender, packageId);
    }

    function registerAndInvestWithId(uint256 sponsorId, uint256 packageId) external nonReentrant {
        address sponsor = idToAddress[sponsorId];
        if (sponsor == address(0)) revert InvalidSponsor();
        _registerAndInvestInternal(sponsor, packageId);
    }

    /**
     * @notice Register and invest in an AnyDexAI package
     * @param sponsor Address of the referrer
     * @param packageId ID of the package to purchase
     */
    function registerAndInvest(address sponsor, uint256 packageId) public nonReentrant {
        _registerAndInvestInternal(sponsor, packageId);
    }

    function _registerAndInvestInternal(address sponsor, uint256 packageId) internal {
        if (!users[msg.sender].isRegistered) {
            if (sponsor == address(0) || sponsor == msg.sender) revert InvalidSponsor();
            if (!users[sponsor].isRegistered && sponsor != owner()) revert SponsorNotActive();
            uint256 sId = addressToId[sponsor];
            _registerUserInternal(msg.sender, sponsor, sId);
        }
        _investInternal(msg.sender, packageId);
    }

    function _registerUserInternal(address userAddr, address sponsorAddr, uint256 sponsorId) internal {
        totalUsers += 1;
        currentId = totalUsers;
        uint256 newUserId = totalUsers;

        idToAddress[newUserId] = userAddr;
        userList[newUserId] = userAddr;
        addressToId[userAddr] = newUserId;

        User storage user = users[userAddr];
        user.isExist = true;
        user.id = newUserId;
        user.isRegistered = true;
        user.sponsor = sponsorAddr;
        user.referrerID = sponsorId;
        user.sponsorID = sponsorId;
        user.lastReferralTimestamp = block.timestamp;
        user.currentMonthStartTime = block.timestamp;
        user.lastLevelAccrualTime = block.timestamp;

        // Push child into sponsor's direct referrals list (BnbSmarttMatrix style)
        users[sponsorAddr].referrals.push(userAddr);
        users[sponsorAddr].directCount += 1;
        users[sponsorAddr].lastReferralTimestamp = block.timestamp;

        // Mint Entry Pass NFT (one-time on registration)
        if (address(nftContract) != address(0)) {
            nftContract.mintEntryPass(userAddr);
        }

        emit Registered(userAddr, sponsorAddr, newUserId, block.timestamp);
    }

    function _investInternal(address userAddr, uint256 packageId) internal {
        if (packageId < 1 || packageId > packageCount) revert InvalidPackage();
        Package memory pkg = packages[packageId];
        if (!pkg.isActive) revert PackageInactive();

        User storage user = users[userAddr];

        // Transfer USDT from user to contract
        usdtToken.safeTransferFrom(userAddr, address(this), pkg.amount);

        // Deduct 0.5% Token Liquidity + 0.5% NFT Liquidity
        uint256 tokenLiqAmount = (pkg.amount * tokenLiquidityBps) / BPS_DENOMINATOR;
        uint256 nftLiqAmount = (pkg.amount * nftLiquidityBps) / BPS_DENOMINATOR;
        usdtToken.safeTransfer(tokenLiquidityWallet, tokenLiqAmount);
        usdtToken.safeTransfer(nftLiquidityWallet, nftLiqAmount);

        // Update User Capital
        user.activeCapital += pkg.amount;
        user.totalCapitalInvested += pkg.amount;

        // Snapshot economic terms in Investment struct
        userInvestments[userAddr].push(Investment({
            capital: uint128(pkg.amount),
            totalRoiClaimed: 0,
            startTime: uint48(block.timestamp),
            lastClaimTime: uint48(block.timestamp),
            packageId: uint32(packageId),
            roiBasisPoints: uint16(pkg.roiBasisPoints),
            durationDays: uint16(pkg.durationDays),
            completed: false
        }));

        // Mint ADAI Tokens: User Tokens + 50% to direct sponsor
        if (address(adaiToken) != address(0) && pkg.tokenReward > 0) {
            adaiToken.mint(userAddr, pkg.tokenReward);
            adaiToken.mint(user.sponsor, pkg.tokenReward / 2); // 50% sponsor tokens
        }

        // Process Immediate Direct Referral Transfers (3 Levels) & Update Downlines
        _processReferralAndDownlines(userAddr, pkg.amount);

        emit Invested(userAddr, packageId, pkg.amount);
    }

    // --- Direct Referral & Downline Tracking ---

    function _processReferralAndDownlines(address buyer, uint256 amount) internal {
        address upline = users[buyer].sponsor;

        // Level 1: 7%
        if (upline != address(0)) {
            _creditReferralBonus(upline, buyer, 1, (amount * directReferralL1Bps) / BPS_DENOMINATOR);
            userDownlineCount[upline][1] += 1;
            userDownlineVolume[upline][1] += amount;
            users[upline].level1Business += amount;
            users[upline].totalTeamBusiness += amount;

            // Level 2: 2%
            address upline2 = users[upline].sponsor;
            if (upline2 != address(0)) {
                _creditReferralBonus(upline2, buyer, 2, (amount * directReferralL2Bps) / BPS_DENOMINATOR);
                userDownlineCount[upline2][2] += 1;
                userDownlineVolume[upline2][2] += amount;
                users[upline2].totalTeamBusiness += amount;

                // Level 3: 1%
                address upline3 = users[upline2].sponsor;
                if (upline3 != address(0)) {
                    _creditReferralBonus(upline3, buyer, 3, (amount * directReferralL3Bps) / BPS_DENOMINATOR);
                    userDownlineCount[upline3][3] += 1;
                    userDownlineVolume[upline3][3] += amount;
                    users[upline3].totalTeamBusiness += amount;

                    // Propagate volume further for Levels 4 to 8 (NFT & Level tracking)
                    address currentUpline = users[upline3].sponsor;
                    for (uint8 lvl = 4; lvl <= 8; ) {
                        if (currentUpline == address(0)) break;
                        userDownlineCount[currentUpline][lvl] += 1;
                        userDownlineVolume[currentUpline][lvl] += amount;
                        users[currentUpline].totalTeamBusiness += amount;
                        currentUpline = users[currentUpline].sponsor;
                        unchecked { ++lvl; }
                    }
                }
            }
        }
    }

    function _creditReferralBonus(address beneficiary, address fromUser, uint8 level, uint256 rawAmount) internal {
        User storage recipient = users[beneficiary];
        _refreshMonthlyCap(recipient);

        uint256 maxAllowed = recipient.activeCapital * MAX_EARNINGS_MULTIPLIER;
        uint256 payableAmount = rawAmount;

        if (recipient.currentMonthEarnings + rawAmount > maxAllowed) {
            if (maxAllowed > recipient.currentMonthEarnings) {
                payableAmount = maxAllowed - recipient.currentMonthEarnings;
            } else {
                payableAmount = 0;
            }
        }

        if (payableAmount > 0) {
            recipient.currentMonthEarnings += payableAmount;
            usdtToken.safeTransfer(beneficiary, payableAmount);
            emit DirectReferralPaid(beneficiary, fromUser, level, payableAmount);
        }

        if (rawAmount > payableAmount) {
            emit DirectReferralCapped(beneficiary, fromUser, level, rawAmount, payableAmount);
        }
    }

    function _refreshMonthlyCap(User storage u) internal {
        if (block.timestamp >= u.currentMonthStartTime + MONTH_DURATION) {
            u.currentMonthStartTime = block.timestamp;
            u.currentMonthEarnings = 0;
        }
    }

    // --- ROI Accrual & Claiming (Snapshotted Terms & 200% Cap) ---

    /**
     * @notice Calculate claimable ROI for a specific investment
     * @dev Uses the exact snapshotted economic terms of the investment!
     */
    function calculateClaimableRoi(address userAddr, uint256 invIndex) public view returns (uint256) {
        if (invIndex >= userInvestments[userAddr].length) return 0;
        Investment memory inv = userInvestments[userAddr][invIndex];
        if (inv.completed) return 0;

        uint256 durationSec = uint256(inv.durationDays) * 1 days;
        if (durationSec == 0) durationSec = 30 days;

        uint256 timeElapsed = block.timestamp - inv.lastClaimTime;
        uint256 maxRoi = uint256(inv.capital) * 2; // 200% Cap
        if (inv.totalRoiClaimed >= maxRoi) return 0;

        // Linear accrual based on SNAPSHOTTED package ROI % and duration
        uint256 accrued = (uint256(inv.capital) * uint256(inv.roiBasisPoints) * timeElapsed) / (durationSec * BPS_DENOMINATOR);
        if (inv.totalRoiClaimed + accrued > maxRoi) {
            accrued = maxRoi - inv.totalRoiClaimed;
        }
        return accrued;
    }

    /**
     * @notice Claim accrued ROI for an investment. When 200% is reached, returns capital in ADAI tokens!
     */
    function claimRoi(uint256 invIndex) external nonReentrant {
        address userAddr = msg.sender;
        if (invIndex >= userInvestments[userAddr].length) revert IndexOutOfBounds();

        Investment storage inv = userInvestments[userAddr][invIndex];
        if (inv.completed) revert InvestmentAlreadyCompleted();

        uint256 claimable = calculateClaimableRoi(userAddr, invIndex);
        uint256 maxRoi = uint256(inv.capital) * 2;
        if (claimable < minWithdrawal && (inv.totalRoiClaimed + claimable != maxRoi)) {
            revert BelowMinWithdrawal();
        }

        inv.totalRoiClaimed += uint128(claimable);
        inv.lastClaimTime = uint48(block.timestamp);

        // Transfer USDT ROI immediately
        usdtToken.safeTransfer(userAddr, claimable);
        emit RoiClaimed(userAddr, invIndex, claimable);

        // Check if 200% ROI ceiling is reached
        if (inv.totalRoiClaimed >= maxRoi) {
            inv.completed = true;
            if (users[userAddr].activeCapital >= inv.capital) {
                users[userAddr].activeCapital -= inv.capital;
            } else {
                users[userAddr].activeCapital = 0;
            }

            // Return Capital via ADAI Tokens upon 200% completion!
            if (address(adaiToken) != address(0)) {
                uint256 adaiToMint = (uint256(inv.capital) * adaiCapitalRefundRate) / 1e18;
                adaiToken.mint(userAddr, adaiToMint);
                emit CapitalReturnedViaADAI(userAddr, invIndex, adaiToMint);
            }
        }
    }

    // --- 5-Level Income Calculation & 120-Day Rule ---

    /**
     * @notice Check if a user is eligible for Level Income on a specific level (1 to 5)
     */
    function isLevelEligible(address userAddr, uint8 level) public view returns (bool) {
        if (level < 1 || level > 5) return false;
        if (userAddr == owner()) return true; // Owner defaultly has maximum levels unlocked
        LevelCriteria memory crit = levelConfigs[level];

        if (level == 1) {
            if (users[userAddr].directCount < crit.requiredMembers) return false;
            if (users[userAddr].level1Business < crit.requiredTeamVolume) return false;
        } else {
            if (userDownlineCount[userAddr][level] < crit.requiredMembers) return false;

            uint256 cumulativeVolume = 0;
            for (uint8 l = 1; l <= level; ) {
                cumulativeVolume += userDownlineVolume[userAddr][l];
                unchecked { ++l; }
            }
            if (cumulativeVolume < crit.requiredTeamVolume) return false;
        }

        return true;
    }

    /**
     * @notice Check 120-day activity rule: must refer at least 1 user within 120 days of previous referral
     */
    function is120DaysActive(address userAddr) public view returns (bool) {
        if (userAddr == owner()) return true; // Owner is always active by default
        if (!users[userAddr].isRegistered) return false;
        return (block.timestamp - users[userAddr].lastReferralTimestamp <= ACTIVITY_WINDOW_DAYS);
    }

    /**
     * @notice Calculate accrued level income for user across 5 levels
     */
    function calculateLevelIncome(address userAddr) public view returns (uint256) {
        User memory u = users[userAddr];
        if (userAddr != owner() && u.activeCapital == 0) return 0;
        if (block.timestamp <= u.lastLevelAccrualTime) return 0;

        uint256 timeElapsed = block.timestamp - u.lastLevelAccrualTime;
        uint256 totalAccrued = 0;

        for (uint8 lvl = 1; lvl <= 5; ) {
            if (isLevelEligible(userAddr, lvl)) {
                LevelCriteria memory crit = levelConfigs[lvl];
                uint256 levelVol = userDownlineVolume[userAddr][lvl];
                if (levelVol > 0) {
                    uint256 inc = (levelVol * crit.roiBps * timeElapsed) / (MONTH_DURATION * BPS_DENOMINATOR);
                    totalAccrued += inc;
                }
            }
            unchecked { ++lvl; }
        }
        return totalAccrued;
    }

    /**
     * @notice Withdraw Level Income (Enforces 120-Day Activity Rule, 2x Cap & Carries Forward Unpaid Remainder!)
     */
    function withdrawLevelIncome() external nonReentrant {
        address userAddr = msg.sender;
        User storage u = users[userAddr];
        if (!u.isRegistered) revert InvalidSponsor();

        // Strict 120-Day Rule Verification
        if (!is120DaysActive(userAddr)) revert ActivityRuleViolated();

        uint256 accrued = calculateLevelIncome(userAddr);
        uint256 totalClaimable = u.pendingLevelIncome + accrued;
        if (totalClaimable < minWithdrawal) revert BelowMinWithdrawal();

        _refreshMonthlyCap(u);
        uint256 payableAmount = totalClaimable;

        if (userAddr != owner()) {
            uint256 maxMonthly = u.activeCapital * MAX_EARNINGS_MULTIPLIER;
            if (u.currentMonthEarnings + totalClaimable > maxMonthly) {
                if (maxMonthly > u.currentMonthEarnings) {
                    payableAmount = maxMonthly - u.currentMonthEarnings;
                } else {
                    payableAmount = 0;
                }
            }

            if (payableAmount == 0) revert ReachedMonthlyCeiling();
        }

        // CRITICAL PRODUCTION HARDENING: Retain unpaid remainder in pendingLevelIncome so it carries forward!
        uint256 unpaidRemainder = totalClaimable - payableAmount;
        u.pendingLevelIncome = unpaidRemainder;
        u.lastLevelAccrualTime = block.timestamp;
        u.currentMonthEarnings += payableAmount;

        usdtToken.safeTransfer(userAddr, payableAmount);
        emit LevelIncomeWithdrawn(userAddr, payableAmount, unpaidRemainder);
    }

    // --- NFT Grade Claiming (Royal NFTs 1 to 8) ---

    function claimNFTGrade(uint8 gradeId) external nonReentrant {
        if (gradeId < 1 || gradeId > 8) revert InvalidGrade();
        address userAddr = msg.sender;
        if (address(nftContract) == address(0)) revert NFTNotConfigured();
        if (nftContract.hasGrade(userAddr, gradeId)) revert GradeAlreadyClaimed();

        NFTGradeCriteria memory crit = nftGradeConfigs[gradeId];

        if (userDownlineCount[userAddr][crit.level] < crit.requiredMembers) revert InsufficientLevelMembers();
        if (userDownlineVolume[userAddr][crit.level] < crit.requiredVolume) revert InsufficientLevelVolume();

        nftContract.mintRoyalNFT(userAddr, gradeId);
        emit NFTGradeClaimed(userAddr, gradeId);
    }

    // --- Admin Package Management ---

    function _createPackage(uint256 amount, uint256 roiBps, uint256 durationDays, uint256 tokenReward) internal {
        packageCount++;
        packages[packageCount] = Package({
            amount: amount,
            roiBasisPoints: roiBps,
            durationDays: durationDays,
            tokenReward: tokenReward,
            isActive: true
        });
        emit PackageAdded(packageCount, amount, roiBps, durationDays, tokenReward);
    }

    function addPackage(uint256 amount, uint256 roiBps, uint256 durationDays, uint256 tokenReward) external onlyOwner {
        if (amount == 0) revert AmountZero();
        if (durationDays == 0) revert DurationZero();
        if (roiBps == 0 || roiBps > 5000) revert InvalidRoiPercentage();
        _createPackage(amount, roiBps, durationDays, tokenReward);
    }

    function updatePackage(
        uint256 packageId,
        uint256 amount,
        uint256 roiBps,
        uint256 durationDays,
        uint256 tokenReward,
        bool isActive
    ) external onlyOwner {
        if (packageId < 1 || packageId > packageCount) revert InvalidPackage();
        if (amount == 0) revert AmountZero();
        if (durationDays == 0) revert DurationZero();
        if (roiBps == 0 || roiBps > 5000) revert InvalidRoiPercentage();

        packages[packageId] = Package({
            amount: amount,
            roiBasisPoints: roiBps,
            durationDays: durationDays,
            tokenReward: tokenReward,
            isActive: isActive
        });
        emit PackageUpdated(packageId, amount, roiBps, durationDays, tokenReward, isActive);
    }

    function updatePackageRoiAndDuration(
        uint256 packageId,
        uint256 newRoiBps,
        uint256 newDurationDays
    ) external onlyOwner {
        if (packageId < 1 || packageId > packageCount) revert InvalidPackage();
        if (newDurationDays == 0) revert DurationZero();
        if (newRoiBps == 0 || newRoiBps > 5000) revert InvalidRoiPercentage();

        Package storage pkg = packages[packageId];
        uint256 oldRoiBps = pkg.roiBasisPoints;
        uint256 oldDuration = pkg.durationDays;

        pkg.roiBasisPoints = newRoiBps;
        pkg.durationDays = newDurationDays;

        emit PackageRoiAndDurationUpdated(packageId, oldRoiBps, newRoiBps, oldDuration, newDurationDays);
    }

    function setDirectReferralPercentages(uint256 l1Bps, uint256 l2Bps, uint256 l3Bps) external onlyOwner {
        if (l1Bps + l2Bps + l3Bps > 2000) revert ReferralPercentageTooHigh();
        directReferralL1Bps = l1Bps;
        directReferralL2Bps = l2Bps;
        directReferralL3Bps = l3Bps;
    }

    function setLevelCriteria(uint8 level, uint256 roiBps, uint256 requiredMembers, uint256 requiredVolume) external onlyOwner {
        if (level < 1 || level > 5) revert IndexOutOfBounds();
        levelConfigs[level] = LevelCriteria(roiBps, requiredMembers, requiredVolume);
    }

    function setNFTGradeCriteria(uint8 gradeId, uint8 level, uint256 requiredMembers, uint256 requiredVolume) external onlyOwner {
        if (gradeId < 1 || gradeId > 8) revert InvalidGrade();
        nftGradeConfigs[gradeId] = NFTGradeCriteria(level, requiredMembers, requiredVolume);
    }

    function setLiquidityWallets(address _tokenLiqWallet, address _nftLiqWallet, uint256 _tokenBps, uint256 _nftBps) external onlyOwner {
        if (_tokenLiqWallet == address(0) || _nftLiqWallet == address(0)) revert ZeroAddress();
        if (_tokenBps + _nftBps > 500) revert FeeTooHigh();
        tokenLiquidityWallet = _tokenLiqWallet;
        nftLiquidityWallet = _nftLiqWallet;
        tokenLiquidityBps = _tokenBps;
        nftLiquidityBps = _nftBps;
    }

    function setMinWithdrawal(uint256 _minWithdrawal) external onlyOwner {
        minWithdrawal = _minWithdrawal;
    }

    // --- Owner Treasury Withdrawal ---

    function adminWithdrawUSDT(uint256 amount, address recipient) external onlyOwner nonReentrant {
        if (recipient == address(0)) revert ZeroAddress();
        uint256 contractBalance = usdtToken.balanceOf(address(this));
        if (amount > contractBalance) revert InsufficientUSDTBalance();

        usdtToken.safeTransfer(recipient, amount);
        emit AdminWithdrawal(recipient, amount);
    }

    // --- View Helpers ---

    function getUserInvestmentsCount(address user) external view returns (uint256) {
        return userInvestments[user].length;
    }

    function getUserInvestment(address user, uint256 index) external view returns (Investment memory) {
        if (index >= userInvestments[user].length) revert IndexOutOfBounds();
        return userInvestments[user][index];
    }

    /**
     * @notice Get all direct referrals of a user (BnbSmarttMatrix style)
     */
    function getUserReferrals(address _user) external view returns (address[] memory) {
        return users[_user].referrals;
    }

    /**
     * @notice Get upline sponsor at a given depth (BnbSmarttMatrix style)
     */
    function getUserUpline(address _user, uint256 _depth) public view returns (address) {
        address current = _user;
        for (uint256 i = 0; i < _depth; i++) {
            address sponsor = users[current].sponsor;
            if (sponsor == address(0)) return owner();
            current = sponsor;
        }
        return current;
    }

    /**
     * @notice Check if a user is active on a level / has active capital (BnbSmarttMatrix style)
     */
    function isLevelActive(address _user, uint256 /* _level */) external view returns (bool) {
        return users[_user].isRegistered && users[_user].activeCapital > 0;
    }

    /**
     * @notice Check if a user is registered / exists (BnbSmarttMatrix style)
     */
    function isUserRegistered(address _user) external view returns (bool) {
        return users[_user].isRegistered || users[_user].isExist;
    }
}

